        const char *separator = memchr(key_data, '=', len_query);
        size_t len_key = separator
                       ? (separator - (char *)key_data)
                       : len_query;

        if (memcmp(key, key_data, len_key)) {
            continue;
        }

        if (value == NULL) {
            return true;
        }

        assert(len);
        if (separator) {
            *value = separator + 1;
            *len = len_query - len_key - 1;
        } else {
            *value = NULL;
            *len   = 0;
        }
        return true;
    }

    return false;
}

