    if (len_key >= key_len) {
        return -E2BIG;
    }

    /* Copy key */
    memcpy(key, key_data, len_key);
    key[len_key] = '\0';

    if (separator) {
        /* key=value format */
        size_t len_val = len_query - len_key - 1;

        /* Check if value buffer is large enough */
        if (len_val >= value_len) {
            return -E2BIG;
        }

        /* Copy value */
        memcpy(value, separator + 1, len_val);
        value[len_val] = '\0';
        return 2;
    } else {
        /* key only format */
        if (value_len > 0) {
            value[0] = '\0';
        }
        return 1;
    }
}
